for(const language of ['en','zh'])Object.assign(words[language],commerceWords[language]);
const moneyFen=value=>'¥'+(Number(value||0)/100).toFixed(2);
function requestKey(){return crypto.randomUUID();}
function operationForm(title,specs,submit){
 const form=el('form',undefined,'actions operation-form');form.append(el('h3',t(title)));const controls={};
 for(const spec of specs){const label=el('label',t(spec.key));let input;if(spec.options){input=el('select');for(const [value,key]of spec.options){const option=el('option',t(key));option.value=value;input.append(option);}}else{input=el(spec.multiline?'textarea':'input');if(spec.multiline)input.rows=3;else input.type='text';input.maxLength=spec.maxLength||2000;if(spec.money){input.inputMode='decimal';input.pattern='[0-9]+(\\.[0-9]{1,2})?';}}
 input.required=spec.required!==false;if(spec.value!==undefined)input.value=String(spec.value);label.append(input);form.append(label);controls[spec.key]={input,spec};}
 const send=el('button',t(title),'primary');send.type='submit';form.append(send);let retry=null;
 form.onsubmit=event=>{event.preventDefault();if(!form.reportValidity())return;run(async()=>{const values={};for(const [key,{input,spec}]of Object.entries(controls)){const value=input.value.trim();if(spec.money){if(!/^\d+(\.\d{1,2})?$/.test(value))throw new Error(t('invalidInput'));const [whole,fraction='']=value.split('.');const fen=Number(whole)*100+Number(fraction.padEnd(2,'0'));if(!Number.isSafeInteger(fen))throw new Error(t('invalidInput'));values[key]=fen;}else values[key]=value;}
 const fingerprint=JSON.stringify(values);if(!retry||retry.fingerprint!==fingerprint)retry={fingerprint,requestId:requestKey()};await submit({...values,requestId:retry.requestId});retry=null;say(t('success'));});};$('detail').append(form);return form;
}
async function commerceWorkflow(orderId){
 const response=await api('/admin/orders/'+orderId+'/workflow'),pane=$('detail'),wf=response.workflow;if(!wf){pane.append(el('p',t('empty')));return;}const data=wf.data;
 pane.append(el('h3',t('workflow')),fields([['status',t(data.stage)],['version',wf.version],['deadline',data.acceptanceDue?date(data.acceptanceDue):'—'],...['availableFen','unsettledFen','frozenFen','commissionFen'].map(key=>[key,moneyFen(data[key])]),['refundAmount',moneyFen(data.refundedFen)]]));
 for(const item of response.cases||[]){pane.append(el('h3',t('cases')+' · '+item.id),fields([['status',item.data.state],['reason',item.data.reason],['description',item.data.description],['refundAmount',moneyFen(item.data.amountFen)],['deadline',item.data.due?date(item.data.due):'—']]));if(item.data.ruling)pane.append(fields(['findings','evidenceSummary','ruleReference','reasoning','obligations'].map(key=>[key,item.data.ruling[key]])));}
 const evidence=el('div',undefined,'evidence-grid');for(const file of response.evidence||[]){if(!file.url)continue;if(file.kind==='evidenceVideo'){const video=el('video');video.controls=true;video.preload='metadata';video.src=file.url;evidence.append(video);}else{const img=el('img');img.src=file.url;img.alt=t('evidence');evidence.append(img);}}if(evidence.childNodes.length)pane.append(el('h3',t('evidence')),evidence);
 const active=(response.cases||[]).find(item=>item.id===data.activeCaseId);
 const definitions={intervene:[],ruling:['caseId','amountFen','findings','evidenceSummary','ruleReference','reasoning','obligations'],evidenceExtension:['caseId','reason'],evidenceApprove:['reason'],refundDispatch:['caseId'],refundOutcome:['caseId','outcome'],riskFreeze:['holdId','amountFen','reason'],riskRelease:['holdId','reason'],specialOpen:['ticketId','amountFen','reason']};
 for(const action of response.allowedActions||[]){if(!(action in definitions))continue;const names=response.allowedActionFields?.[action]||definitions[action],specs=names.filter(key=>!['requestId','version','action'].includes(key)).map(key=>({key,money:key==='amountFen',multiline:['findings','evidenceSummary','ruleReference','reasoning','obligations','reason'].includes(key),...(key==='caseId'?{value:active?.id||''}:{}),...(key==='amountFen'?{value:((active?.data.amountFen||0)/100).toFixed(2)}:{}),...(key==='outcome'?{options:[['pending','pending'],['success','successResult'],['failure','failureResult']]}:{})}));operationForm(action,specs,async values=>{await api('/admin/orders/'+orderId+'/actions',{...values,version:wf.version,action});await orderDetail(orderId);await load();});}
 if(response.events?.length)pane.append(el('h3',t('events')),table(['created','action','name'],response.events.map(event=>[date(event.createdAt),t(event.action),event.actorId||'—'])));
}
async function ticketDetail(id){const {ticket}=await api('/admin/tickets/'+id);$('detail').replaceChildren(fields([['id',ticket.id],['kind',ticket.kind],['status',t(ticket.status)],['text',ticket.text],['created',date(ticket.createdAt)]]));for(const reply of ticket.replies||[])$('detail').append(fields([['text',reply.text],['created',date(reply.createdAt)]]));operationForm('reply',[{key:'status',options:[['inProgress','inProgress'],['replied','replied'],['closed','closed']]},{key:'text',multiline:true}],async values=>{await api('/admin/tickets/'+id+'/reply',values);await ticketDetail(id);await load();});}
function queueDetail(kind,item){$('detail').replaceChildren(el('p',t('simulationFinance'),'muted'),fields([['id',item.id||item.key],['seller',item.sellerId],['status',t(item.status||'')],['amount',moneyFen(item.amountFen)],['name',item.label||item.accountLabel||'—'],['reason',item.reason],['created',item.createdAt?date(item.createdAt):'—']]));
 if(kind==='withdrawals'&&!['succeeded','failed'].includes(item.status))operationForm('outcome',[{key:'status',options:[['processing','processing'],['succeeded','succeeded'],['failed','failed']]},{key:'reason',multiline:true}],async values=>{await api('/admin/withdrawals/'+item.id+'/outcome',values);$('dialog').close();await load();});
 if(kind==='payouts')operationForm('verifyAccount',[{key:'verified',options:[['true','approved'],['false','changes_requested']]},{key:'reason',multiline:true}],async values=>{await api('/admin/payouts/'+item.id+'/verify',{...values,verified:values.verified==='true'});$('dialog').close();await load();});
 if(kind==='ledger')$('detail').append(fields(['reference','kind','availableDelta','unsettledDelta','frozenDelta','reservedDelta','commissionDelta'].map(key=>[key,key.endsWith('Delta')?moneyFen(item[key]):item[key]])));
}
async function loadCommerce(){const data=await api('/admin/commerce?'+new URLSearchParams({section,page:String(page)}));hasMore=!!data.hasMore;const items=data.items||[],c=$('content');let headings,rows;
 if(section==='cases'){headings=['id','status','reason','action'];rows=items.map(item=>[item.id,item.data.state,item.data.reason,button(t('view'),()=>openDetail(t('orders'),()=>orderDetail(item.orderId)))]);}
 else if(section==='tickets'){headings=['kind','status','text','created','action'];rows=items.map(item=>[item.kind,t(item.status),item.text,date(item.createdAt),button(t('view'),()=>openDetail(t('tickets'),()=>ticketDetail(item.id)))]);}
 else if(section==='ledger'){headings=['created','kind','amount','reference','action'];rows=items.map(item=>[date(item.createdAt),item.kind,moneyFen(item.availableDelta),item.reference,button(t('view'),()=>openDetail(t('ledger'),()=>queueDetail(section,item)))]);}
 else if(section==='jobs'){headings=['id','kind','deadline','status'];rows=items.map(item=>[item.orderId,item.kind,date(item.dueAt),item.done?t('completed'):t('pending')]);}
 else{headings=['name','seller','status','amount','action'];rows=items.map(item=>[item.label||item.accountLabel,item.sellerId,t(section==='payouts'?(item.verified?'approved':'pending'):item.status),section==='payouts'?'—':moneyFen(item.amountFen),button(t('view'),()=>openDetail(t(section),()=>queueDetail(section,item)))]);}
 const notice=el('p',t('simulationFinance'),'muted');c.replaceChildren(notice,table(headings,rows));if(section==='jobs')c.prepend(button(t('runJobs'),async()=>{await api('/admin/jobs/run',{});await load();},'primary'));$('page').textContent=t('page')+' '+page;$('previous').dataset.disabled=String(page===1);$('next').dataset.disabled=String(!hasMore);
}

let lang=localStorage.getItem('sammy-admin-language')==='en'?'en':'zh', token=null,busy=false,section='overview',page=1,hasMore=false,detailLoader=null;
const t=k=>words[lang][k]||k;
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const date=v=>new Date(v).toLocaleString(lang==='zh'?'zh-CN':'en-GB');
const badge=(text,kind='')=>el('span',text,'badge '+kind);
function button(text,handler,cls){const b=el('button',text,cls);b.type='button';b.onclick=()=>run(handler);return b;}
function say(text){$('notice').textContent=text;$('detailNotice').textContent=text;$('authNotice').textContent=text;}
async function api(path,body){const r=await fetch('/v1'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(30000)});const d=await r.json();if(!r.ok){if(r.status===401||d.error==='accountSuspended'){token=null;showLogin();}throw new Error(t(d.error||'failed'));}return d;}
async function run(fn){if(busy)return;busy=true;say(t('working'));document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();say('');}catch(e){say(e.message||t('failed'));}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=b.dataset.disabled==='true');}}
function showLogin(){document.body.classList.add('signed-out');$('loginLanguage').value=lang;$('passwordInput').type='password';passwordToggleLabel();$('login').hidden=false;$('workspace').hidden=true;$('logout').hidden=true;$('dialog').close();renderNav();}
function renderNav(){$('nav').replaceChildren();for(const key of ['overview','users','providers','applications','services','orders',...commerceSections,'history']){const b=button(t(key),async()=>{section=key;page=1;$('query').value='';await load();});b.className=section===key?'active':'';b.disabled=!token;b.dataset.disabled=String(!token);$('nav').append(b);}}
function translate(){document.documentElement.lang=lang;$('language').value=lang;$('loginLanguage').value=lang;passwordToggleLabel();for(const [id,key] of Object.entries({eyebrow:'eyebrow',title:section,subtitle:section+'Sub',loginTitle:'loginTitle',loginEyebrow:'loginEyebrow',loginSubtitle:'loginSubtitle',loginFootnote:'loginFootnote',phoneLabel:'phone',passwordLabel:'password',signIn:'signIn',logout:'logout',searchButton:'search',refresh:'refresh',previous:'previous',next:'next'}))$(id).textContent=t(key);$('query').placeholder=t('searchHint');for(const o of $('status').options)o.textContent=t(o.value);renderNav();}
function table(headings,rows){const wrap=el('div',undefined,'table-wrap');if(!rows.length){wrap.append(el('div',t('empty'),'empty'));return wrap;}const table=el('table'),head=el('thead'),hr=el('tr');for(const h of headings)hr.append(el('th',t(h)));head.append(hr);table.append(head);const body=el('tbody');for(const cells of rows){const row=el('tr');for(const [index,value] of cells.entries()){const cell=el('td');if(headings[index]==='reason')cell.className='reason';if(value instanceof Node)cell.append(value);else cell.textContent=String(value??'—');row.append(cell);}body.append(row);}table.append(body);wrap.append(table);return wrap;}
function nameCell(name,sub){const n=el('div',name);n.append(el('small',sub));return n;}
function openDetail(title,loader){$('detailTitle').textContent=title;detailLoader=loader;return loader().then(()=>{if(!$('dialog').open)$('dialog').showModal();});}
function fields(pairs){const dl=el('dl');for(const [key,value]of pairs)dl.append(el('dt',t(key)),el('dd',String(value??'—')));return dl;}
function photos(files){for(const f of files||[]){if(!f.url)continue;if(f.kind==='voice'){const a=el('audio');a.controls=true;a.src=f.url;$('detail').append(a);}else{const img=el('img');img.src=f.url;img.alt=t('name');$('detail').append(img);}}}
function reasonActions(actions,note){const form=el('form',undefined,'actions'),label=el('label',t('reason')),reason=el('textarea');reason.rows=3;reason.minLength=5;reason.maxLength=1000;reason.required=true;reason.placeholder=t('reasonHint');label.append(reason);form.append(label);if(note)form.append(el('p',t(note),'muted'));for(const [key,fn,danger]of actions)form.append(button(t(key),async()=>{if(!reason.reportValidity()||reason.value.trim().length<5)throw new Error(t('reasonHint'));await fn(reason.value.trim());$('dialog').close();await load();},danger?'danger':'primary'));$('detail').append(form);}
async function userDetail(id){const d=await api('/admin/users/'+id),u=d.profile,pane=$('detail');pane.replaceChildren(fields([['id',u.id],['name',u.nickname],['phone',u.phone],['bio',u.bio],['status',t(u.suspended?'suspended':'active')],['reason',u.suspensionReason],['providers',t(u.providerSuspended?'suspended':'active')],['note',u.providerSuspensionReason],['created',date(u.createdAt)]]));photos(d.files);pane.append(el('h3',t('applications')),table(['status','submitted','action'],d.applications.map(a=>[t(a.status),date(a.submittedAt),button(t('review'),()=>applicationDetail(a.id))])));pane.append(el('h3',t('services')),table(['name','status'],d.listings.map(l=>[l.title,t(l.moderationBlocked?'blocked':l.status)])));if(u.isAdmin){pane.append(el('p',t('protected'),'muted'));return;}const provider=d.applications.some(a=>a.status==='approved');reasonActions([[u.suspended?'reactivate':'suspend',reason=>api('/admin/users/'+id+'/status',{suspended:!u.suspended,reason}),!u.suspended],...(provider?[[u.providerSuspended?'reactivateProvider':'suspendProvider',reason=>api('/admin/providers/'+id+'/status',{suspended:!u.providerSuspended,reason}),!u.providerSuspended]]:[])]);}
async function serviceDetail(id){const {listing:l,owner,files}=await api('/admin/services/'+id),pane=$('detail');pane.replaceChildren(fields([['id',l.id],['name',l.title],['owner',owner.nickname+' / '+owner.phone],['description',l.description],['price','¥'+(l.priceFen/100).toFixed(2)],['status',t(l.status)],['moderation',t(l.moderationBlocked?'blocked':'active')],['reason',l.moderationReason],['revision',l.revision]]));photos(files);reasonActions([[l.moderationBlocked?'restore':'block',reason=>api('/admin/services/'+id+'/moderation',{blocked:!l.moderationBlocked,reason,revision:l.revision}),!l.moderationBlocked]],'restoreNote');}
async function applicationDetail(id){const {application:a,files}=await api('/admin/applications/'+id),pane=$('detail');pane.replaceChildren(fields([['name',a.snapshot.nickname],['bio',a.snapshot.bio],['status',t(a.status)],['submitted',date(a.submittedAt)],['agreement',a.agreementVersion],['note',a.reason]]));const draftLabels={gameName:['游戏昵称','Game nickname'],gameId:['游戏编号','Game ID'],server:['区服','Server'],rank:['段位','Rank'],kd:['KD','KD'],experience:['陪玩经验','Experience'],playStyle:['风格','Play style'],mode:['模式','Mode']};const dl=el('dl');for(const [key,v]of Object.entries(a.snapshot.draft)){if(key==='voiceMediaId')continue;dl.append(el('dt',draftLabels[key]?.[lang==='zh'?0:1]||key),el('dd',String(v)));}pane.append(dl);photos(files);pane.append(el('p',t('reviewNote'),'muted'));if(a.status==='pending'){const hasMedia=files.some(f=>f.kind==='avatar'&&f.url)&&files.some(f=>f.kind==='voice'&&f.url);if(!hasMedia)pane.append(el('p',t('mediaMissing')));reasonActions([...(hasMedia?[['approve',reason=>api('/admin/applications/'+id+'/review',{decision:'approved',reason}),false]]:[]),['changes',reason=>api('/admin/applications/'+id+'/review',{decision:'changes_requested',reason}),true]]);}}
async function orderDetail(id){const {order:o,attempts}=await api('/admin/orders/'+id),pane=$('detail');pane.replaceChildren(el('p',t('simulation'),'muted'),fields([['id',o.id],['name',o.service.title],['buyer',o.buyerId],['seller',o.sellerId],['status',t(o.status)],['quantity',o.quantity],['amount','¥'+(o.totalFen/100).toFixed(2)],['created',date(o.createdAt)],['description',o.service.description],['rules',o.rules.version+' · '+o.rules.text[lang]]]));pane.append(fields([['name',o.delivery.gameName],['id',o.delivery.gameId],['note',o.delivery.note]]),el('h3',t('payments')),table(['id','status','created'],attempts.map(a=>[a.id,t(a.status==='pending'?'pendingPayment':a.status==='failed'?'failedPayment':a.status),date(a.createdAt)])));if(o.paidAt)await commerceWorkflow(id);}
async function load(){translate();if(commerceSections.includes(section)){$('tools').hidden=true;$('pager').hidden=false;await loadCommerce();return;}$('tools').hidden=section==='overview';$('search').hidden=['history','applications','orders'].includes(section);$('status').hidden=section!=='applications';$('pager').hidden=['overview','applications'].includes(section);const c=$('content');if(section==='overview'){const {totals}=await api('/admin/overview'),cards=el('div',undefined,'cards');for(const [key,value]of [['totalUsers',totals.users],['totalProviders',totals.providers],['pendingReviews',totals.pending],['totalServices',totals.services],['liveServices',totals.published],['suspendedUsers',totals.suspended]]){const card=el('div',undefined,'panel metric');card.append(el('p',t(key)),el('strong',value));cards.append(card);}const intro=el('div',undefined,'panel intro');intro.append(el('p',t('intro')),el('p',t('publicNote')));c.replaceChildren(cards,intro);return;}
const d=await api('/admin/'+section+'?'+new URLSearchParams(section==='applications'?{status:$('status').value}:section==='orders'?{page:String(page)}:{q:$('query').value,page:String(page)}));hasMore=!!d.hasMore;let rows,heads;if(['users','providers'].includes(section)){heads=['name','phone','status','created','action'];rows=d.items.map(u=>[nameCell(u.nickname,u.isAdmin?t('protected'):u.id),u.phone,badge(t(u.suspended?'suspended':section==='providers'&&u.providerSuspended?'providerSuspended':'active'),u.suspended||section==='providers'&&u.providerSuspended?'bad':''),date(u.createdAt),button(t('view'),()=>openDetail(t(section),()=>userDetail(u.id)))]);}else if(section==='applications'){heads=['name','status','submitted','action'];rows=d.applications.map(a=>[a.nickname,badge(t(a.status),a.status==='pending'?'warn':''),date(a.submittedAt),button(t('review'),()=>openDetail(t('review'),()=>applicationDetail(a.id)))]);}else if(section==='services'){heads=['name','owner','price','status','action'];rows=d.items.map(({listing:l,nickname,suspended,providerSuspended})=>[nameCell(l.title,l.id),nickname,'¥'+(l.priceFen/100).toFixed(2),badge(t(l.moderationBlocked?'blocked':suspended||providerSuspended?'suspended':l.status),l.moderationBlocked||suspended||providerSuspended?'bad':''),button(t('view'),()=>openDetail(t('services'),()=>serviceDetail(l.id)))]);}else if(section==='orders'){heads=['name','status','amount','created','action'];rows=d.items.map(o=>[nameCell(o.service.title,o.id),badge(t(o.status)), '¥'+(o.totalFen/100).toFixed(2),date(o.createdAt),button(t('view'),()=>openDetail(t('orders'),()=>orderDetail(o.id)))]);}else{heads=['created','name','action','id','reason'];rows=d.items.map(a=>[date(a.createdAt),a.actor,actionLabel(a.action),a.targetId,a.reason||'—']);}c.replaceChildren(table(heads,rows));$('page').textContent=t('page')+' '+page;$('previous').dataset.disabled=String(page===1);$('next').dataset.disabled=String(!hasMore);}
function actionLabel(action){const [area,verb]=action.split('.');return t(area==='application'?'applications':area)+' · '+t({suspend:'suspend',reactivate:'reactivate',block:'block',restore:'restore',approved:'approved',changes_requested:'changes_requested'}[verb]||verb);}
$('login').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target),d=await api('/auth/login',{phone:f.get('phone'),password:f.get('password')});token=d.token;e.target.reset();$('loginLanguage').value=lang;$('passwordInput').type='password';passwordToggleLabel();if(!d.profile.isAdmin){await api('/auth/logout',{});token=null;throw new Error(t('adminRequired'));}document.body.classList.remove('signed-out');$('passwordInput').type='password';passwordToggleLabel();$('login').hidden=true;$('workspace').hidden=false;$('logout').hidden=false;await load();});};
$('logout').onclick=()=>run(async()=>{await api('/auth/logout',{});token=null;showLogin();});$('search').onsubmit=e=>{e.preventDefault();page=1;run(load);};$('status').onchange=()=>run(load);$('refresh').onclick=()=>run(load);$('previous').onclick=()=>run(async()=>{page--;await load();});$('next').onclick=()=>run(async()=>{page++;await load();});$('close').onclick=()=>{$('dialog').close();detailLoader=null;};function changeLanguage(event){lang=event.target.value;localStorage.setItem('sammy-admin-language',lang);translate();if(token)run(async()=>{await load();if($('dialog').open&&detailLoader){$('detailTitle').textContent=t(section==='applications'?'review':section);await detailLoader();}});}$('language').onchange=changeLanguage;$('loginLanguage').onchange=changeLanguage;function passwordToggleLabel(){const shown=$('passwordInput').type==='text';$('passwordToggle').textContent=t(shown?'hide':'show');$('passwordToggle').setAttribute('aria-label',t(shown?'hidePassword':'showPassword'));$('passwordToggle').setAttribute('aria-pressed',String(shown));}$('passwordToggle').onclick=()=>{$('passwordInput').type=$('passwordInput').type==='password'?'text':'password';passwordToggleLabel();};translate();showLogin();
